BN.configureOwnerSelect=()=>{
 if(BN.user.role!=='manager')return;
 const input=document.getElementById('owner'),select=document.createElement('select');
 select.id='owner';select.setAttribute('aria-label','Nhân viên phụ trách');input.replaceWith(select);
 BN.ownerMembers=[BN.user];
 BN.syncOwnerSelect=name=>{
  const current=String(name||''),members=BN.ownerMembers||[];
  select.replaceChildren();
  const add=(name,phone,label=name)=>{const option=document.createElement('option');option.value=name;option.textContent=label;option.dataset.phone=phone||'';select.append(option);};
  if(!current)add('','','Chọn nhân viên phụ trách');
  if(current&&!members.some(member=>member.name===current))add(current,state.ownerPhone||'');
  for(const member of members)add(member.name,member.phone,member.position?`${member.name} · ${member.position}`:member.name);
  select.value=current;
 };
};

