 const pushSupportMessage=()=>{const ua=navigator.userAgent||'',ios=/iPad|iPhone|iPod/.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);if(location.protocol!=='https:')return 'Cần mở bằng link HTTPS để bật thông báo.';if(!('serviceWorker'in navigator))return 'Trình duyệt này chưa hỗ trợ Service Worker.';if(!('PushManager'in window))return ios?'iPhone cần bấm Chia sẻ → Thêm vào Màn hình chính, rồi mở web từ icon mới để bật thông báo.':'Trình duyệt/app đang mở chưa hỗ trợ Web Push. Trên Android nên mở bằng Chrome.';if(!('Notification'in window))return 'Trình duyệt này chưa hỗ trợ thông báo.';return '';};
