 const refreshPushButton=async()=>{if(!pushButton)return;const unsupported=pushSupportMessage();if(unsupported)return setPushUnsupported(unsupported);try{const reg=await navigator.serviceWorker.register(pushWorkerUrl,{scope:'/'}),sub=await reg?.pushManager.getSubscription(),blocked=Notification.permission==='denied';if(sub)BN.api('/push/subscribe','POST',sub.toJSON()).catch(()=>{});const label=sub?'Push đang bật':blocked?'Push bị chặn':'Bật push';pushButton.hidden=false;pushButton.textContent=label;pushButton.disabled=blocked;pushButton.title=blocked?'Thông báo đang bị chặn trong cài đặt trình duyệt/điện thoại.':'Bật thông báo trên thiết bị này';mobilePushButton.textContent=sub?'Đã bật thông báo':blocked?'Push bị chặn':'Bật thông báo';mobilePushButton.disabled=blocked;mobilePushButton.title=pushButton.title;mobilePushButton.hidden=Boolean(sub)||blocked;}catch{pushButton.hidden=false;pushButton.disabled=false;pushButton.textContent='Bật push';pushButton.title='Bật thông báo trên thiết bị này';mobilePushButton.textContent='Bật thông báo';mobilePushButton.disabled=false;mobilePushButton.hidden=false;}};
 const enablePush=async()=>{const unsupported=pushSupportMessage();if(unsupported){await refreshPushButton();return toast(unsupported);}const config=await BN.api('/push/config');if(!config.enabled||!config.publicKey)return toast('Web push chưa được cấu hình khóa VAPID trên server.');const permission=await Notification.requestPermission();if(permission!=='granted'){await refreshPushButton();return toast('Anh cần cho phép thông báo trong trình duyệt.');}const reg=await navigator.serviceWorker.register(pushWorkerUrl,{scope:'/'});let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:pushKeyToBytes(config.publicKey)});await BN.api('/push/subscribe','POST',sub.toJSON());await refreshPushButton();toast('Đã bật thông báo web push trên thiết bị này.');};
