 const markDirtyModal=event=>{const target=event.target;if(!target||typeof target.closest!=='function'||typeof target.matches!=='function')return;if(!target.matches('input, textarea, select, [contenteditable="true"]'))return;const modal=target.closest('.modal');if(modal&&dirtyModalLabels[modal.id])modal.dataset.clawDirty='1';};
